package packet; public final class PayloadClassifier{public String classify(byte[] payload){if(payload==null||payload.length==0)return"empty";String s=new String(payload,0,Math.min(payload.length,32),java.nio.charset.StandardCharsets.ISO_8859_1);if(s.startsWith("GET ")||s.startsWith("POST ")||s.startsWith("HEAD "))return"http-request";if(s.startsWith("HTTP/"))return"http-response";int printable=0;for(byte b:payload){int c=b&255;if(c==9||c==10||c==13||(c>=32&&c<127))printable++;}return printable*100/payload.length>85?"text":"binary";}}
